const cFind = q => { const s = abNorm(q); let best;
  for (const a of CARCH) for (const [b, ab] of a.br) for (const [n, d] of ab) if (s.includes(abNorm(n)) && (!best || n.length > best[2].length)) best = [a, b, n, d];
  return best; };
// Chips bundle each base archetype with its upgrade; hybrids build on two bases so they stand alone.
const CGROUP = [["Recruiter", ["Recruiter","Elite Recruiter"]], ["Motivator", ["Motivator","Master Motivator"]], ["Tactician", ["Tactician","Scheme Guru"]],
  ["Architect", ["Architect"]], ["Strategist", ["Strategist"]], ["Talent Developer", ["Talent Developer"]],
  ["Program Builder & CEO", ["Program Builder","CEO"]], ["Rainmaker & Visionary", ["Rainmaker","Visionary"]]];
// Per-upgrade cost from the archetype's cost text: "15, 20, 25, 30 CP per tier (K/P: Hot Hand 10, Locked In 15)", "20 CP per tier", "40 CP each, ...".
// K/P discounts are per ability (prestonchoate.dev game-file data); an ability not listed costs K/P the same as every other group.
function cCost(a){
  const four = x => x.length === 1 ? [x[0], x[0], x[0], x[0]] : x;
  let m = a.cost.match(/^([\d, ]+) CP per tier(?: \(K\/P: (.+)\))?$/);
  if (m) return {tier:four(m[1].split(/,\s*/).map(Number)), kp:m[2] ? Object.fromEntries(m[2].split(/,\s*(?=[A-Z])/).map(x => { const k = x.match(/^(.+) (\d+)$/); return [k[1], +k[2]]; })) : {}};
  m = a.cost.match(/^(\d+) CP each/); return m ? {each:+m[1]} : null;
}
const cTierCost = (a, i, n) => { const c = cCost(a); return !c ? null : c.each ? [c.each, null] : [c.tier[i], c.kp[n] ?? null]; };
function cDrawAb(q){
  $("#abArch").innerHTML = CGROUP.map(([g]) => `<button type="button" class="chip ab-cchip" data-c="${esc(g)}" aria-pressed="${!q && g === abC}">${CGROUP.find(x => x[0] === g)[1].map(n => abImg("a", n)).join("")}${esc(g)}</button>`).join("");
  let ico = false;
  const row = (a, i, t, n, d, p) => { let c = cTierCost(a, i, n); if (c && p) c = [p === "K/P" ? c[1] ?? c[0] : c[0], null];
    return `<li>${ico ? abImg("c", n) || '<span class="ab-slot"></span>' : ""}<div class="ab-tx">${t ? `<span class="ab-tier">Tier ${t}</span>` : ""}<b class="ab-nm">${esc(n)}</b><span class="ab-ds">${esc(d)}</span></div>`
      + `${c ? `<em class="ab-cost"><span class="ab-coin" aria-label="${c[0]} coach points">${c[0]}</span>${c[1] != null && c[1] !== c[0] ? `<small>K/P ${c[1]}</small>` : ""}</em>` : ""}</li>`; };
  const card = (a, b, ab, all, p) => `<section class="sl-card"><h3>${esc(p || b)}${all ? "" : `<span>${esc(a.n)}</span>`}</h3><ul class="ab-list ab-clist${(ico = ab.some(([n]) => abImg("c", n))) ? "" : " noico"}">${
    ab.map(([n, d], i) => all || n.toLowerCase().includes(q) ? row(a, i, a.n === "CEO" || a.g === "Special" ? 0 : i + 1, n, d, p) : "").join("")}</ul></section>`;
  if (q) {
    const hits = CARCH.flatMap(a => a.br.filter(([, ab]) => ab.some(([n]) => n.toLowerCase().includes(q))).map(([b, ab]) => card(a, b, ab, false)));
    $("#abCGrid").innerHTML = hits.length ? `<div class="sl-grid">${hits.join("")}</div>` : `<p class="hint">No coach ability matches "${esc(q)}".</p>`;
    return;
  }
  $("#abCGrid").innerHTML = CGROUP.find(g => g[0] === abC)[1].map(n => CARCH.find(x => x.n === n)).map(a =>
    `<section class="ab-arch"><h3 class="ab-ah">${abImg("a", a.n)}${esc(a.n)} <span>${esc(a.g)}</span></h3>`
    + `<div class="ab-meta"><dl><div><dt>Unlock</dt><dd>${esc(a.u)}</dd></div>${a.perk ? `<div><dt>Perk</dt><dd>${esc(a.perk)}</dd></div>` : ""}</dl></div>`
    + `<div class="sl-grid">${a.br.flatMap(([b, ab]) => a.pos ? CPOS.map(p => card(a, b, ab, true, p)) : [card(a, b, ab, true)]).join("")}</div></section>`).join("");
}
// Abilities view in the URL: #abilities/cb, #abilities/favorites, #abilities/coach/recruiter, #abilities/position-changes.
TSUB.ab = () => abM === "chg" ? "/position-changes" : abM === "coach" ? "/coach/" + abSlug(abC) : "/" + abSlug(abP === "FAV" ? "favorites" : abP);
function abFromHash(sub){
  const [a, b] = sub.split("/");
  if (a === "position-changes") abM = "chg";
  else if (a === "coach") { abM = "coach"; const g = CGROUP.find(g => abSlug(g[0]) === b); if (g) abC = g[0]; }
  else { const p = [...ABPOS, "FAV"].find(p => abSlug(p === "FAV" ? "favorites" : p) === a); if (p) { abM = "player"; abP = p; } }
}
function abDraw(){
  if (curTab === "ab") tabHash();
  const q = $("#abQ").value.trim().toLowerCase();
  $("#abMode").innerHTML = [["player","Player"],["coach","Coach"],["chg","Position changes"]].map(([k, t]) => `<button type="button" class="chip" data-m="${k}" aria-pressed="${k === abM}">${t}</button>`).join("");
  $("#abPlayer").hidden = abM !== "player"; $("#abCoach").hidden = abM !== "coach"; $("#abChg").hidden = abM !== "chg"; $("#abQ").hidden = abM === "chg";
  if (abM === "chg") return pcDraw();
  $("#abQ").placeholder = abM === "player" ? "Search an ability, e.g. Sure Hands" : "Search an ability, e.g. Portal King";
  if (abM === "coach") return cDrawAb(q);
  $("#abPos").innerHTML = ABPOS.map(p => { const f = ABFAV.filter(k => k.startsWith(p + "|")).length; return `<button type="button" class="chip" data-p="${p}" aria-pressed="${!q && p === abP}">${p}${f ? ` <span class="abfn" title="${f} favorite${f > 1 ? "s" : ""}">★${f}</span>` : ""}</button>`; }).join("") + `<button type="button" class="chip" data-p="FAV" aria-pressed="${!q && abP === "FAV"}">★ Favorites${ABFAV.length ? ` <span class="abfn">${ABFAV.length}</span>` : ""}</button>`;
  const orph = ["K/P", "Archetype not confirmed", Object.keys(ABPHYS).filter(n => !abWho(n).length)];
  const arch = (q ? [...ABARCH, orph].filter(a => a[2].some(n => n.toLowerCase().includes(q))) : [...ABARCH, orph].filter(a => abP === "FAV" ? ABFAV.includes(a[0] + "|" + a[1]) : a[0] === abP)).filter(a => a[2].length).sort((a, b) => ABFAV.includes(b[0] + "|" + b[1]) - ABFAV.includes(a[0] + "|" + a[1]));
  $("#abGrid").innerHTML = arch.length ? arch.map(([p, n, ab]) => `<section class="sl-card"><h3>${esc(n)}<span>${p}${p === "K/P" ? "" : (f => `<button type="button" class="abfav" data-fav="${esc(p + "|" + n)}" aria-pressed="${f}" aria-label="${f ? "Remove" : "Add"} ${esc(n)} ${f ? "from" : "to"} favorites" title="${f ? "Unfavorite" : "Favorite"}">${f ? "★" : "☆"}</button>`)(ABFAV.includes(p + "|" + n))}</span></h3><ul class="ab-list">${ab.map(x => abRow(x, p + "|" + n)).join("")}</ul></section>`).join("")
    : `<p class="hint">${q ? `No archetype has a physical ability matching "${esc(q)}".` : "No favorites yet. Tap the ☆ on an archetype to add it."}</p>`;
  $("#abMent").innerHTML = Object.keys(ABMENT).filter(n => !q || n.toLowerCase().includes(q)).map(abRow).join("");
}
// Clicking the active Favorites chip again turns the filter off, back to the last position.
let abLast = "QB";
$("#abPos").addEventListener("click", e => { const b = e.target.closest("[data-p]"); if (!b) return; const p = b.dataset.p;
  if (p === "FAV" && abP === "FAV" && !$("#abQ").value.trim()) abP = abLast; else { if (abP !== "FAV") abLast = abP; abP = p; }
  $("#abQ").value = ""; abDraw(); });
$("#abMode").addEventListener("click", e => { const b = e.target.closest("[data-m]"); if (b) { abM = b.dataset.m; $("#abQ").value = ""; abDraw(); } });
$("#abArch").addEventListener("click", e => { const b = e.target.closest("[data-c]"); if (b) { abC = b.dataset.c; $("#abQ").value = ""; abDraw(); } });
$("#abGrid").addEventListener("click", e => { const b = e.target.closest("[data-fav]"); if (b) abFav(b.dataset.fav); });
$("#abQ").addEventListener("input", abDraw);

// Position change planner (abM "chg"): saved {id, fp, fa, tp, ta, note} in poschg-v1; ta "" = new archetype not known.
let PC = []; try { PC = (JSON.parse(localStorage.getItem("poschg-v1")) || []).filter(c => c && c.fp && c.tp); } catch (e) {}
const pcSave = () => { try { localStorage.setItem("poschg-v1", JSON.stringify(PC)); } catch (e) {} };
const pcPos = ABPOS.filter(p => p !== "K/P");
const pcArch = p => ABARCH.filter(a => a[0] === p).map(a => a[1]);
const pcOpts = (sel, list, keep, none) => { const v = keep ?? sel.value; sel.innerHTML = (none ? `<option value="">${none}</option>` : "") + list.map(x => `<option>${esc(x)}</option>`).join(""); if (list.includes(v)) sel.value = v; };
// Note boxes grow to fit their text, so long notes stay fully visible (skipped while hidden, when there's nothing to measure).
const pcFit = el => { if (!el.offsetParent) return; el.style.height = "auto"; el.style.height = el.scrollHeight + 2 + "px"; };
function pcDraw(){
  if (!$("#pcFp").options.length) { pcOpts($("#pcFp"), pcPos); pcOpts($("#pcTp"), pcPos, "WR"); }
  pcOpts($("#pcFa"), pcArch($("#pcFp").value));
  pcOpts($("#pcTa"), pcArch($("#pcTp").value), null, "Not sure yet");
  $("#pcAdd").disabled = $("#pcFp").value === $("#pcTp").value;
  $("#pcList").innerHTML = PC.length ? PC.map(c => `<section class="sl-card pc-card"><h3>${esc(c.fp)} &rarr; ${esc(c.tp)}<button type="button" class="pc-del" data-del="${c.id}" aria-label="Delete this change" title="Delete">&times;</button></h3>
    <p class="pc-move"><b>${esc(c.fa)}</b> <span>${esc(c.fp)}</span> <i>&rarr;</i> ${c.ta ? `<b>${esc(c.ta)}</b>` : `<b class="pc-unk">Not sure yet</b>`} <span>${esc(c.tp)}</span></p><textarea class="pc-n" data-note="${c.id}" rows="1" maxlength="200" placeholder="Add a note" aria-label="Note for ${esc(c.fa)} ${esc(c.fp)} to ${esc(c.tp)}">${esc(c.note || "")}</textarea></section>`).join("")
    : `<p class="hint">No position changes saved yet.</p>`;
  document.querySelectorAll("#pcList .pc-n").forEach(pcFit);
}
for (const id of ["#pcFp", "#pcTp"]) $(id).addEventListener("change", pcDraw);
$("#pcAdd").addEventListener("click", () => {
  const c = {id: Date.now().toString(36), fp: $("#pcFp").value, fa: $("#pcFa").value, tp: $("#pcTp").value, ta: $("#pcTa").value, note: $("#pcNote").value.trim()};
  if (c.fp === c.tp) return;
  PC.push(c); pcSave(); $("#pcNote").value = ""; $("#pcNote").style.height = ""; pcDraw();
});
// Notes edit in place and save as you type; no redraw, so the box keeps focus.
$("#pcList").addEventListener("input", e => { const c = e.target.dataset.note && PC.find(x => x.id === e.target.dataset.note); if (c) { c.note = e.target.value.trim(); pcSave(); pcFit(e.target); } });
$("#pcNote").addEventListener("input", e => pcFit(e.target));
addEventListener("resize", () => document.querySelectorAll("#pcList .pc-n, #pcNote").forEach(pcFit));   // narrower cards need taller notes
$("#pcList").addEventListener("click", e => { const b = e.target.closest("[data-del]"); if (b && confirm("Delete this position change?")) { PC = PC.filter(c => c.id !== b.dataset.del); pcSave(); pcDraw(); } });
abDraw();
